-- ============================================================
-- Direct MySQL import generated from All_Coordinators_Issues_v11.xlsx
-- Run:  mysql -u <user> -p <db_name> < import_from_excel.sql
-- Idempotent: re-running inserts nothing new.
-- ============================================================
SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;

-- ============================================================
-- PURGE: removes previously imported data (the earlier import put
-- every VidhanSabha/Panchayat under the wrong district). Users with
-- TEACHER/REGIONAL_ADMIN roles are removed; admin/superuser kept.
-- NOTE: this also clears StudentAttendance rows (test data).
-- ============================================================
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM CenterAssignUser;
DELETE FROM StudentAttendance;
DELETE FROM RegionalAdminPanchayat;
DELETE FROM Student;
DELETE FROM Teacher;
DELETE FROM RegionalAdmin;
DELETE FROM Center;
DELETE FROM School;
DELETE FROM Village;
DELETE FROM Panchayat;
DELETE FROM VidhanSabha;
DELETE FROM District;
DELETE FROM Users WHERE RoleId IN (SELECT Id FROM Role WHERE RoleCode IN ('TEACHER', 'REGIONAL_ADMIN'));
SET FOREIGN_KEY_CHECKS = 1;

SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

